    id: state.cycleId,
    ms: elapsed,
    dbOps: state.dbOps,
    apiOps: state.apiOps,
  });
}

function orchestrate<T>(label: string, fn: () => T): T {
  beginCycle(label);
  try { return fn(); } finally { endCycle(); }
